using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text;
using System.Web.Script.Serialization;
namespace PZ3D {
 static class ConfigOrder127Tests {
  static readonly JavaScriptSerializer Json=new JavaScriptSerializer();
  static int failures,assertions;
  static readonly string[] Default11={"ZombieBuddy","Viewpoint","B42ModTrans_CN","B42Trans_CN","LaoYuTranslationJava","PZVoxelStudioViewpoint","ShootToThrillMultiplayer","OrangeShootPresentation","ProjectViewpointShelves","ViewpointTrueWeathers","ProjectViewpointNearVegetation"};
  sealed class Fixture {
   public readonly Engine E;public readonly string Root;
   public Fixture(){Root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"order-fixtures",Guid.NewGuid().ToString("N"));E=new Engine(Path.Combine(Root,"steamapps/common/ProjectZomboid"),Path.Combine(Root,"user"),Path.Combine(Root,"data"),true);Put(E.Config,"{\"vmArgs\":[\"-Xmx2g\"]}");Put(Path.Combine(E.Game,"ProjectZomboid64.exe"),"fixture-never-executed");Put(Path.Combine(E.Game,"game-version.txt"),"42.12.3");}
   public void Mod(string id,string metadata=""){Put(Path.Combine(E.User,"mods",id,"42/mod.info"),"id="+id+"\n"+metadata);}
   public void Default(params string[] ids){string text="VERSION = 1,\r\nmods\r\n{\r\n"+string.Concat(ids.Select(id=>"    mod = "+id+",\r\n"))+"}\r\nmaps\r\n{\r\n    map = Muldraugh, KY,\r\n}\r\ncustom\r\n{\r\n    original = untouched,\r\n}\r\n";Directory.CreateDirectory(Path.GetDirectoryName(E.Mods));File.WriteAllText(E.Mods,text,new UTF8Encoding(true));}
   public void Actual(){foreach(string id in Default11)Mod(id);Mod("LaoYuTranslationJava","loadModAfter=ViewpointTrueWeathers\n");Default(Default11);}
  }
  static void Put(string path,string text){Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,text,new UTF8Encoding(false));}
  static Dictionary<string,object> D(object value){return Json.Deserialize<Dictionary<string,object>>(Json.Serialize(value));}
  static string[] Strings(Dictionary<string,object> value,string name){return ((IEnumerable)value[name]).Cast<object>().Select(x=>x.ToString()).ToArray();}
  static Dictionary<string,object> ModsItem(Engine e,string targetKind="normal"){return ((IEnumerable)D(LaunchPreflight.Check(e,false,false,targetKind))["items"]).Cast<Dictionary<string,object>>().Single(i=>(string)i["id"]=="mods");}
  static Dictionary<string,object> Auto(Engine e,bool confirmed){var method=typeof(ModConfigurations).GetMethod("AutoSortDefault");Assert(method!=null,"default automatic repair API exists");try{return D(method.Invoke(null,new object[]{e,confirmed}));}catch(TargetInvocationException ex){throw ex.InnerException;}}
  static Dictionary<string,object> Save(Engine e,string[] ids){return D(ModConfigurations.Save(e,new Dictionary<string,object>{{"name","Fixture draft"},{"mods",ids},{"stamp",D(ModConfigurations.List(e))["stamp"]}}));}
  static void Assert(bool value,string message){assertions++;if(!value)throw new Exception(message);}
  static string Refuses(Action work){try{work();}catch(Exception ex){return ex.Message;}throw new Exception("operation unexpectedly succeeded");}
  static void Case(string name,Action work){try{work();Console.WriteLine("PASS "+name);}catch(Exception ex){failures++;Console.WriteLine("FAIL "+name+": "+ex.Message);}}
  // Break caught: the installed eleven-ID graph loses its specific soft-order evidence.
  static void ActualDetails(){var f=new Fixture();f.Actual();byte[] before=File.ReadAllBytes(f.E.Mods);var item=ModsItem(f.E);Assert(item.ContainsKey("details")&&item.ContainsKey("canAutoSort"),"mods preflight supplies details and automatic-repair eligibility");Assert((bool)item["canAutoSort"]&&(string)item["status"]=="error","valid changed graph offers explicit automatic repair");Assert(Strings(item,"details").Any(s=>s.Contains("ViewpointTrueWeathers")&&s.Contains("LaoYuTranslationJava")&&s.IndexOf("ViewpointTrueWeathers",StringComparison.Ordinal)<s.IndexOf("LaoYuTranslationJava",StringComparison.Ordinal)),"violated edge identifies ViewpointTrueWeathers before LaoYuTranslationJava");Assert(before.SequenceEqual(File.ReadAllBytes(f.E.Mods)),"details check leaves actual default bytes untouched");}
  // Break caught: automatic repair enables/removes IDs, damages non-mod blocks, or rewrites an already-correct file.
  static void Repair(){var f=new Fixture();f.Actual();byte[] before=File.ReadAllBytes(f.E.Mods);Refuses(()=>Auto(f.E,false));Assert(before.SequenceEqual(File.ReadAllBytes(f.E.Mods)),"unconfirmed repair never writes");string tail=File.ReadAllText(f.E.Mods).Substring(File.ReadAllText(f.E.Mods).IndexOf("maps",StringComparison.Ordinal));var result=Auto(f.E,true);string[] expected={"ZombieBuddy","Viewpoint","B42ModTrans_CN","B42Trans_CN","PZVoxelStudioViewpoint","ShootToThrillMultiplayer","OrangeShootPresentation","ProjectViewpointShelves","ViewpointTrueWeathers","LaoYuTranslationJava","ProjectViewpointNearVegetation"};Assert((bool)result["changed"]&&Strings(result,"mods").SequenceEqual(expected),"stable automatic repair moves LaoYu after the selected weather predecessor");Assert(Strings(result,"mods").OrderBy(x=>x,StringComparer.Ordinal).SequenceEqual(Default11.OrderBy(x=>x,StringComparer.Ordinal)),"repair preserves exact ID membership");Assert(File.ReadAllBytes(f.E.Mods).Take(3).SequenceEqual(new byte[]{239,187,191})&&File.ReadAllText(f.E.Mods).EndsWith(tail,StringComparison.Ordinal),"repair preserves UTF-8 BOM and maps/custom blocks");var item=ModsItem(f.E);Assert(!(bool)item["canAutoSort"]&&(string)item["status"]=="ok"&&Strings(item,"details").Length==0,"fresh preflight clears repaired edge and action");File.SetLastWriteTimeUtc(f.E.Mods,new DateTime(2001,1,1,0,0,0,DateTimeKind.Utc));before=File.ReadAllBytes(f.E.Mods);result=Auto(f.E,true);Assert(!(bool)result["changed"]&&before.SequenceEqual(File.ReadAllBytes(f.E.Mods))&&File.GetLastWriteTimeUtc(f.E.Mods).Year==2001,"second repair is a real no-write operation");Assert(!Directory.Exists(f.E.Data),"default repair does not depend on named profile storage");}
  // Break caught: stale UI evidence is used instead of reading the current default, or unknown IDs disappear.
  static void FreshMembership(){var f=new Fixture();f.Actual();ModsItem(f.E);f.Mod("NewIndependent");f.Default("LaoYuTranslationJava","NewIndependent","UnknownPreserved","ViewpointTrueWeathers");var result=Auto(f.E,true);Assert(Strings(result,"mods").SequenceEqual(new[]{"NewIndependent","UnknownPreserved","ViewpointTrueWeathers","LaoYuTranslationJava"}),"repair re-reads current membership and preserves unverified opaque IDs");}
  // Break caught: dependency errors are hidden or invalid graphs are offered/written as automatic repairs.
  static void Invalid(){foreach(string kind in new[]{"missing","conflict","cycle"}){var f=new Fixture();f.Mod("A",kind=="missing"?"require=MissingParent\n":kind=="conflict"?"conflicts=B\n":"require=B\n");f.Mod("B",kind=="cycle"?"loadModAfter=A\n":"");f.Default("A","B");byte[] before=File.ReadAllBytes(f.E.Mods);var item=ModsItem(f.E);Assert(item.ContainsKey("details")&&item.ContainsKey("canAutoSort"),"invalid graph exposes details contract");Assert(!(bool)item["canAutoSort"]&&(string)item["status"]=="error","invalid "+kind+" graph does not offer sorting");string[] details=Strings(item,"details");Assert(details.Any(s=>kind=="missing"?s.Contains("A")&&s.Contains("MissingParent"):kind=="conflict"?s.Contains("A")&&s.Contains("B")&&s.Contains("冲突"):s.Contains("A")&&s.Contains("B")&&s.Contains("循环")),"invalid "+kind+" details carry concrete graph evidence");string error=Refuses(()=>Auto(f.E,true));Assert(error.Contains(kind=="missing"?"MissingParent":kind=="conflict"?"冲突":"循环")&&before.SequenceEqual(File.ReadAllBytes(f.E.Mods)),"invalid "+kind+" repair reports cause and preserves bytes");}}
  // Break caught: malformed default syntax is swallowed or automatic repair silently replaces it.
  static void Malformed(){var f=new Fixture();f.Mod("A");Put(f.E.Mods,"mods\n{\n unknown = untouched,\n mod = A,\n}\nmaps\n{\n}\n");byte[] before=File.ReadAllBytes(f.E.Mods);var item=ModsItem(f.E);Assert(item.ContainsKey("details")&&Strings(item,"details").Any(s=>s.Contains("未知语法"))&&!(bool)item["canAutoSort"],"read failure preserves specific syntax detail");Refuses(()=>Auto(f.E,true));Assert(before.SequenceEqual(File.ReadAllBytes(f.E.Mods)),"malformed repair is refused without writes");}
  // Break caught: managed retention prepends a dependent mod ahead of an ordinary predecessor in an already-sorted profile.
  static void Activation(){var f=new Fixture();f.Mod("A");f.Mod("Viewpoint","loadModAfter=A\n");f.Default("Viewpoint");var saved=Save(f.E,new[]{"A","Viewpoint"});ModConfigurations.Activate(f.E,(string)saved["id"],(string)saved["stamp"],true);Assert(SaveProfiles.DefaultMods(File.ReadAllBytes(f.E.Mods)).SequenceEqual(new[]{"A","Viewpoint"}),"activation sorts final managed-plus-profile membership");}
  // Break caught: named drafts require a valid game installation, safe launch arguments, or a finished launch session.
  static void DraftStorage(){var f=new Fixture();f.Default("A");File.Delete(f.E.Config);Put(Path.Combine(f.E.Game,"ProjectZomboid64.bat"),"SET _JAVA_OPTIONS=-agentlib:zbNative");Put(Path.Combine(f.E.Data,"launch-sessions",LaunchProfiles.Key(f.E)+".json"),"synthetic active session");byte[] before=File.ReadAllBytes(f.E.Mods);var saved=Save(f.E,new[]{"A"});Assert((string)saved["name"]=="Fixture draft","named draft saves with missing launch config and active session");ModConfigurations.Delete(f.E,(string)saved["id"],(string)saved["stamp"]);Assert(((IEnumerable)D(ModConfigurations.List(f.E))["profiles"]).Cast<object>().Count()==0&&before.SequenceEqual(File.ReadAllBytes(f.E.Mods)),"named draft deletion remains independent of launch prerequisites");}
  // Break caught: parser exceptions publish raw malformed source-cache contents as UI error details.
  static void SourcePrivacy(){var f=new Fixture();f.Mod("A");f.Default("A");const string secret="fixture-private-parser-value";Put(Path.Combine(f.E.Data,"workshop-paths.json"),secret);byte[] before=File.ReadAllBytes(f.E.Mods);var item=ModsItem(f.E);Assert((string)item["status"]=="error"&&!Json.Serialize(item).Contains(secret),"source parse failure exposes a reason without raw cache contents");string error=Refuses(()=>Auto(f.E,true));Assert(!error.Contains(secret)&&error.Contains("来源")&&before.SequenceEqual(File.ReadAllBytes(f.E.Mods)),"repair source parse refusal does not echo cache contents or write defaults");}
  // Break caught: a second full inventory scan reuses spent directory budget and hides an available server repair.
  static void ServerRepairBudget(){
   var f=new Fixture();f.Mod("ZombieBuddy");f.Mod("Viewpoint","require=ZombieBuddy\n");for(int i=0;i<1500;i++)f.Mod("Independent"+i);
   Put(f.E.Config,"{\"vmArgs\":[\"-Xmx2g\",\"-agentlib:zbNative\"]}");Put(Path.Combine(f.E.Game,"ZombieBuddy.jar"),"fixture-loader");Put(Path.Combine(f.E.Game,"zbNative.dll"),"fixture-native");f.Default("Viewpoint","ZombieBuddy");
   var budget=new LaunchReadBudget(16777216);var preview=ModConfigurations.SortForPreflight(f.E,new[]{"Viewpoint","ZombieBuddy"},budget);Assert(!budget.Incomplete&&preview.errors.Length==0&&preview.changed,"large inventory fits the first bounded scan and has a repairable edge");
   byte[] before=File.ReadAllBytes(f.E.Mods);var item=ModsItem(f.E,"server");Assert((string)item["status"]=="error"&&before.SequenceEqual(File.ReadAllBytes(f.E.Mods)),"server dependency report identifies retained wrong order without writing");
   var repaired=Auto(f.E,true);Assert((bool)repaired["changed"]&&Strings(repaired,"mods").SequenceEqual(new[]{"ZombieBuddy","Viewpoint"}),"fresh automatic repair handles the same bounded inventory");
   Assert((bool)item["canAutoSort"],"server preflight offers the available repair without exhausting a second scan's budget");
  }
  public static int Main(){Case("actual default11 order details",ActualDetails);Case("stable confirmed default repair and idempotence",Repair);Case("fresh default membership",FreshMembership);Case("invalid graph evidence and no-write refusal",Invalid);Case("malformed default evidence and no-write refusal",Malformed);Case("activation final combined order",Activation);Case("named draft storage independence",DraftStorage);Case("source parse error privacy",SourcePrivacy);Case("server repair independent scan budget",ServerRepairBudget);Console.WriteLine("CONFIG ORDER 127: "+assertions+" assertions; "+failures+" failed cases");return failures==0?0:1;}
 }
